// Get the document ID from input
const docId = $input.item.json.document_id || $input.item.json.query || '';

// Search Qdrant directly by document_name metadata
const qdrantUrl = 'http://localhost:6333/collections/nomad_bms_documents/points/scroll';

const searchBody = {
  limit: 10,
  with_payload: true,
  with_vector: false,
  filter: {
    must: [
      {
        key: "document_name",
        match: { text: docId }
      }
    ]
  }
};

const response = await fetch(qdrantUrl, {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(searchBody)
});

const data = await response.json();

// Format results
if (data.result && data.result.points && data.result.points.length > 0) {
  const points = data.result.points;
  const docName = points[0].payload.document_name;

  // Group content by document
  let fullContent = '';
  points.forEach(point => {
    fullContent += point.payload.content + '\n\n';
  });

  const formattedResponse = `**Document Found:** ${docName}\n\n${fullContent}\n\n**Sources:**\n[1] ${docName} (Found ${points.length} sections)`;

  return {
    json: {
      response: formattedResponse,
      document_name: docName,
      chunks_found: points.length,
      status: 'found'
    }
  };
} else {
  return {
    json: {
      response: `Document ID "${docId}" not found in the BMS database. Try searching by document title or topic instead.`,
      status: 'not_found'
    }
  };
}
